import java.util.*;
import org.simplepoint.platform.dictionary.registration.DictionaryRegistrationService;
import org.simplepoint.platform.dictionary.registration.DictionaryLegacyAdoption;
import org.simplepoint.plugin.rbac.tenant.service.initialize.DictionaryLegacyAdoptions;
import org.simplepoint.platform.composition.ModuleCatalog;
import org.simplepoint.remoting.RemoteProvider;
import org.springframework.transaction.annotation.Transactional;

public class VerifyDictionaryAdoptionArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyDictionaryAdoptionArtifacts.class.getClassLoader();
    var plan = ModuleCatalog.discover(loader).plan(List.of("identity"));
    if (!"identity".equals(plan.capabilityOwners().get("security.dictionary-registration:1")))
      throw new AssertionError("Dictionary registration ownership changed");
    if (DictionaryRegistrationService.class.getDeclaredMethods().length != 1
        || !DictionaryRegistrationService.class.getDeclaredMethods()[0].getName().equals("apply")
        || DictionaryLegacyAdoptions.class.isAnnotationPresent(RemoteProvider.class))
      throw new AssertionError("Installer adoption leaked into runtime RPC");
    var adoption = DictionaryLegacyAdoptions.class.getMethod("adopt", DictionaryLegacyAdoption.Command.class);
    if (adoption.getAnnotation(Transactional.class) == null)
      throw new AssertionError("Missing adoption transaction");
    for (Class<?> type : List.of(DictionaryLegacyAdoptions.class, DictionaryLegacyAdoption.class)) {
      var artifacts = Collections.list(loader.getResources(type.getName().replace('.', '/') + ".class"));
      if (artifacts.size() != 1) throw new AssertionError("Missing/duplicate adoption artifact");
    }
    var path = "META-INF/simplepoint/modules/identity/db/";
    if (Collections.list(loader.getResources(path + "postgresql/V8__dictionary_legacy_adoption.sql")).size() != 1)
      throw new AssertionError("Missing/duplicate V8 migration");
    try (var stream = loader.getResourceAsStream(path + "manifest.properties")) {
      var manifest = new Properties(); manifest.load(stream);
      if (!manifest.getProperty("migrations").contains("V8__dictionary_legacy_adoption.sql")
          || !manifest.getProperty("tables").contains("simpoint_dictionary_legacy_adoptions"))
        throw new AssertionError("Adoption schema not declared");
    }
    System.out.println("Installed Common distribution verified: identity-owned local adoption, unchanged narrow runtime RPC, transactional adoption, unique pure contract/provider artifacts and declared V8 migration.");
  }
}
